using Careersity.Api.Infrastructure; using Careersity.Application.ExternalLearning.Requests; using Careersity.Application.ExternalLearning.Services; using Careersity.Domain.Enums; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace Careersity.Api.Controllers;
[ApiController,Authorize(Policy=SecurityPolicies.AdministratorOnly),Route("api/admin/learning-providers"),Tags("Admin External Learning")]
public sealed class AdminLearningProvidersController(ILearningProviderService service):ControllerBase
{
 [HttpPost]public async Task<IActionResult>Create(CreateLearningProviderRequest r,CancellationToken t){var x=await service.CreateAsync(r,t);return CreatedAtAction(nameof(Get),new{id=x.Id},x);}[HttpGet]public async Task<IActionResult>List([FromQuery]int page=1,[FromQuery]int pageSize=20,[FromQuery]string?search=null,[FromQuery]ContentStatus?status=null,CancellationToken t=default)=>Ok(await service.ListAdminAsync(new(page,pageSize,search,status),t));[HttpGet("{id:guid}")]public async Task<IActionResult>Get(Guid id,CancellationToken t)=>Ok(await service.GetAdminAsync(id,t));[HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,UpdateLearningProviderRequest r,CancellationToken t)=>Ok(await service.UpdateAsync(id,r,t));[HttpPost("{id:guid}/publish")]public async Task<IActionResult>Publish(Guid id,CancellationToken t){await service.PublishAsync(id,t);return NoContent();}[HttpPost("{id:guid}/archive")]public async Task<IActionResult>Archive(Guid id,CancellationToken t){await service.ArchiveAsync(id,t);return NoContent();}
}
