[ApiController,Authorize(Policy=SecurityPolicies.AdministratorOnly),Route("api/admin/courses/{courseId:guid}/external-resources"),Tags("Admin External Learning")]
public sealed class AdminCourseExternalResourcesController(ICourseExternalResourceService service):ControllerBase
{
 [HttpPost]public async Task<IActionResult>Assign(Guid courseId,AssignExternalResourceToCourseRequest r,CancellationToken t)=>StatusCode(201,await service.AssignAsync(courseId,r,t));[HttpGet]public async Task<IActionResult>List(Guid courseId,CancellationToken t)=>Ok(await service.ListAdminAsync(courseId,t));[HttpPut("{assignmentId:guid}")]public async Task<IActionResult>Update(Guid courseId,Guid assignmentId,UpdateCourseExternalResourceRequest r,CancellationToken t)=>Ok(await service.UpdateAsync(courseId,assignmentId,r,t));[HttpDelete("{assignmentId:guid}")]public async Task<IActionResult>Remove(Guid courseId,Guid assignmentId,CancellationToken t){await service.RemoveAsync(courseId,assignmentId,t);return NoContent();}[HttpPut("reorder")]public async Task<IActionResult>Reorder(Guid courseId,ReorderCourseExternalResourcesRequest r,CancellationToken t){await service.ReorderAsync(courseId,r,t);return NoContent();}
